import pytest
import numpy as np
from pandas import (Series, DatetimeIndex, DataFrame)
import pandas._testing as tm


def test_groupby_apply_series_returns_series(date_range):
    # GH#37260
    # apply with a Series returns a Series
    s = Series([1, 2, 3])

    def f(x):
        return x + 1

    result = s.groupby(date_range).apply(f)
    expected = Series(np.repeat(2, 3), index=date_range)
    tm.assert_series_equal(result, expected)


def test_groupby_apply_series_returns_dataframe(date_range):
    # apply with a Series returns a DataFrame
    s = Series([1, 2, 3])

    def f(x):
        return x + 1

    result = s.groupby(date_range).apply(lambda x: Series(x))
    expected = DataFrame({0: [1, 2, 3]}, index=date_range)
    tm.assert_frame_equal(result, expected)


def test_groupby_apply_series_multiindex_returns_series(date_range):
    # apply with a Series returns a Series
    s = Series([1, 2, 3], index=[0, 1, 2])

    def f(x):
        return x + 1

    result = s.groupby(date_range, group_keys=False).apply(f)
    expected = Series(np.repeat(2, 3), index=date_range)
    tm.assert_series_equal(result, expected)

